const EDGE_FETCH_CALL_0_PROJECT_SQL = `SELECT ?1 AS "endpoint"`;
const EDGE_FETCH_CALL_0_WRITE_SQL = `INSERT INTO "fetch_call" ("endpoint") VALUES (?)`;
const EDGE_FETCH_CALL_0_HEAD_COLUMNS: readonly string[] = ["endpoint"];

function resolveFetchCall_0Writes(seam: ISqlSeam, before: Snapshot, arrivals: IArrivalBatch): Observable<readonly SqlStatement[]> {
  const triggerRows = triggerOccurrences("set", "fetch_demand", before.fetch_demand, arrivals);
  if (triggerRows.length === 0) return of([]);
  return forkJoin(triggerRows.map((arrival) => seam.runner.execute(seam.db, { sql: EDGE_FETCH_CALL_0_PROJECT_SQL, args: bindArgs(arrival.row) }))).pipe(
    map((results) => {
      const written: SqlStatement[] = [];
      for (const result of results) {
        const projectedRows = result.rows.map((row) => EDGE_FETCH_CALL_0_HEAD_COLUMNS.map((column) => row[column] as IRowValue) as IRow);
        for (const projectedRow of projectedRows) {
          written.push({ sql: EDGE_FETCH_CALL_0_WRITE_SQL, args: bindArgs(projectedRow) });
        }
      }
      return written;
    }),
  );
}

function recomputeLevels(seam: ISqlSeam): Observable<void> {
  const sql = `DELETE FROM "fetch_demand";
INSERT OR IGNORE INTO "fetch_demand" ("endpoint") SELECT b0."endpoint" FROM "stale" b0`;
  return seam.runner.executeMultiple(seam.db, sql);
}

function buildDeltas(before: Snapshot, after: Snapshot): ITickDeltas {
  const fetch_call = multisetDiff(before.fetch_call, after.fetch_call);
  const fetch_demand = multisetDiff(before.fetch_demand, after.fetch_demand);
  const stale = multisetDiff(before.stale, after.stale);
  return {
    rels: [
      { rel: "fetch_call", add: fetch_call.add, del: fetch_call.del },
      { rel: "fetch_demand", add: fetch_demand.add, del: fetch_demand.del },
      { rel: "stale", add: stale.add, del: stale.del },
    ],
    carryPending: fetch_call.add.length > 0 || fetch_call.del.length > 0,
  };
}

function runNaiveTick(seam: ISqlSeam, arrivals: IArrivalBatch): Observable<ITickDeltas> {
  return readSnapshot(seam).pipe(
    concatMap((before) => applyArrivals(seam, arrivals).pipe(map(() => before))),
    concatMap((before) => recomputeLevels(seam).pipe(map(() => before))),
    concatMap((before) =>
      resolveFetchCall_0Writes(seam, before, arrivals).pipe(
        concatMap((statements) => seam.runner.batch(seam.db, statements)),
        map(() => before),
      ),
    ),
    concatMap((before) => recomputeLevels(seam).pipe(map(() => before))),
    concatMap((before) => readSnapshot(seam).pipe(map((after) => buildDeltas(before, after)))),
  );
  // demand_view_fires_its_consumer_once: engine.pl process_occurrences -> level_closure -> boundary_deltas.
}

const INCREMENTAL_PROGRAM_SAFE = true;
const RECONCILE_EVERY_TICK = false;
const EMITTER_MODE = process.env.SPREFA_TSV2_EMITTER_MODE === "naive" ? "naive" : "incremental";

function runIncrementalTick(seam: ISqlSeam, arrivals: IArrivalBatch): Observable<ITickDeltas> {
  return IncrementalRuntime.prepareTick(seam, INCREMENTAL_RELATIONS).pipe(
    concatMap(() => IncrementalRuntime.applyArrivals(seam, arrivals, INCREMENTAL_RELATIONS)),
    concatMap(() => IncrementalRuntime.applyLevelsBeforeEdges(seam, INCREMENTAL_LEVEL_STATEMENTS, INCREMENTAL_RELATIONS)),
    concatMap(() => IncrementalRuntime.recomputeLevelsBeforeEdges(seam, INCREMENTAL_LEVEL_STATEMENTS, INCREMENTAL_RELATIONS, RECONCILE_EVERY_TICK, arrivals)),
    concatMap(() => IncrementalRuntime.applyEdges(seam, INCREMENTAL_EDGE_STATEMENTS, INCREMENTAL_RELATIONS)),
    concatMap(() => IncrementalRuntime.mergeNextIntoCurrent(seam, INCREMENTAL_RELATIONS)),
    concatMap(() => IncrementalRuntime.applyLevelsAfterEdges(seam, INCREMENTAL_LEVEL_STATEMENTS, INCREMENTAL_RELATIONS)),
  ).pipe(
    concatMap(() => IncrementalRuntime.recomputeLevelsAfterEdges(seam, INCREMENTAL_LEVEL_STATEMENTS, INCREMENTAL_RELATIONS, RECONCILE_EVERY_TICK)),
    concatMap(() => IncrementalRuntime.readBoundary(seam, INCREMENTAL_RELATIONS)),
    concatMap((rels) => IncrementalRuntime.promoteFrontiers(seam, INCREMENTAL_RELATIONS).pipe(
      map((carryPending): ITickDeltas => ({ rels, carryPending })),
    )),
  );
}

function runTick(seam: ISqlSeam, arrivals: IArrivalBatch): Observable<ITickDeltas> {
  arrivals = validateArrivals(arrivals);
  // Derived edge triggers consume the P1 current/next frontier, including drain carry.
  return runIncrementalTick(seam, arrivals);
}

